'use strict';

// MODULES //

var minmaxn = require( '@stdlib/math/base/special/minmaxn' );
var floor = require( '@stdlib/math/base/special/floor' );
var round = require( '@stdlib/math/base/special/round' );
var roundn = require( '@stdlib/math/base/special/roundn' );
var ceil = require( '@stdlib/math/base/special/ceil' );
var linearScale = require( './scale/linearScale.js' );


// FUNCTIONS //

/**
* Calculate the appropriate height and width for plot.
* @private
* @param {Array} data raw data to be plot
* @param {Number} height height of the plot axis
* @param {Object} axis height of the plot axis
* @returns {Array} scaled xaxis points
*/
function processXAxisLabel( data, height, axis ) {
	var xaxis;
	var start;
	var mnmx;
	var val;
	var arr;
	var i;
	var d;

	if ( data.length === 0 ) {
		return {
			'data': [],
			'diff': 0,
			'start': 0
		};
	}
	xaxis = [];
	arr = [];
	for ( val of data ) {
		for ( i = 1; i < val.length; i++ ) {
			xaxis.push( val[ i ] );
		}
	}
	mnmx = minmaxn.apply( null, xaxis );
	if ( axis.start === 'auto' ) {
		start = mnmx[ 0 ];
	}
	else {
		start = axis.start;
	}
	d = ceil( ( ( mnmx[ 1 ] - start ) / ( height - 1 ) ) * 1000 ) / 1000;

	i = start;

	while ( i < mnmx[ 1 ] + d ) {
		arr.push( roundn( i, -4 ) );
		i += d;
	}
	return {
		'data': arr,
		'diff': d,
		'start': start
	};
}

/**
* Process the categary.
* @private
* @param {Array} data raw data to be plot
* @param {String} format format string
* @returns {Array} scaled xaxis points
*/
function processCategary( data ) {
	var categaries;
	var val;

	categaries = [];
	for ( val of data ) {
		categaries.push( val[ 0 ] );
	}
	return categaries;
}

