/**
* Process the bar.
* @private
* @param {Number} startRow raw data to be plot
* @param {Number} startCol raw data to be plot
* @param {Object} bar raw data to be plot
* @param {Object} axis raw data to be plot
* @param {Array} data raw data to be plot
* @returns {Array} scaled xaxis points
*/
function processBar( startRow, startCol, bar, axis, data ) {
	var height;
	var barSet;
	var bars;
	var val;
	var i;
	var j;
	var x = startCol;
	var y = startRow;

	barSet = [];
	for ( i = 0; i < data.length; i++ ) {
		bars = [];
		for ( j = 0; j < bar.num; j++ ) {
			height = round( ( data[ i ][ 1 + j ] - axis.start ) / axis.diff );
			val = [];
			val.push( [ y, x ] );
			val.push( [ y + height, x ] );
			val.push( [ y, x + bar.width - 1 ] );
			val.push( [ y + height, x + bar.width - 1 ] );
			bars.push( val );
			x += bar.width;
		}
		barSet.push( bars );
		x += bar.gap;
	}
	return barSet;
}


// MAIN //

/**
* Renders a table.
*
* @private
* @throws {Error} output must be able to accommodate every table column individually
* @returns {string} rendered table
*/
function render() {
	var categoriesWidth;
	var xAxisMetaData;
	var categories;
	var barsSet;
	var bars;
	var val;
	var i;

	xAxisMetaData = processXAxisLabel( this._data, 10, this._xAxisDataObj );
	categories = processCategary( this._data );
	this._baseConstructor.axisData = [ xAxisMetaData.data, categories, [], [] ];

	// this._baseConstructor.labelFormate = [ this.xAxisFormat, this.categoriesFormat, '', '' ];
	this._baseConstructor.drawFrame = true;
	categoriesWidth = ( this.barWidth * this.barsPerLabel ) + this.barGap;
	this._baseConstructor.ticsStride = [ 1, categoriesWidth, 0, 0 ];
	this._baseConstructor.plotAreaWidth = this._data.length * ( categoriesWidth );
	this._baseConstructor.plotAreaHeight = 10;
	this._baseConstructor.initialize();

	barsSet = processBar( this._baseConstructor.plotArea.y + 1, this._baseConstructor.plotArea.x + 1, this._barObj, xAxisMetaData, this._data );

	for ( bars of barsSet ) {
		for ( i = 0; i < this.barsPerLabel; i++ ) {
			val = bars[ i ];
			this._baseConstructor.setBar( val[ 0 ], val[ 1 ], val[ 2 ], val[ 3 ], 'block', this.barsColor[ i ], true );
		}
	}
	return this._baseConstructor.render();
}


// EXPORTS //

module.exports = render;
